            return _newColumnName
        },
    )

get_compensated_value = (temperature, ec) => {
	t20 = temperature-20.0
	A = 1.37023 * t20 + float(v: "8.36e-4")*(t20^2.0)
	B = 109.0 + temperature
	
	C = 0.889 * 10.0^(A/B)
	ec_25 = ec / C
	return ec_25
}

get_calibrated_value = (temperature, ec) => {
  ec_25_raw = get_compensated_value(ec: ec, temperature: temperature)
  //https://aquaponix.webo.family/index.php/apps/files/files/12960?dir=/aquaponics/System/System_SCF/iot&openfile=true
	//m = 0.367082887
  //b = -159.604669
  m = 0.296556512 //neue Koeffizienten ab 7.8.2025 / 11:07
  b = -17.40116689
	return ec_25_raw*m+b
}

